// A TfNotice sent with a vector of paths for attribute that
// have changed. Sent by StageReaderWriter upon request, contains
// the paths of attributes that the StageReaderWriter has flagged
// as modified during it's lifetime, which is typically one frame.
//
// primPaths and attributeNames are required to the same length,
// the prim and attribute name within that prim whose value
// changed
class AttributeValuesChangedNotice : public PXR_NS::TfNotice
{
public:
    AttributeValuesChangedNotice(const std::vector<PXR_NS::SdfPath>& primPaths,
                                 const std::vector<PXR_NS::TfToken>& attributeNames)
        : _primPaths(primPaths), _attributeNames(attributeNames)
    {
    }
    ~AttributeValuesChangedNotice()
    {
    }

    const std::vector<PXR_NS::SdfPath>& GetPrimPaths() const
    {
        return _primPaths;
    }

    const std::vector<PXR_NS::TfToken>& GetAttributeNames() const
    {
        return _attributeNames;
    }

private:
    std::vector<PXR_NS::SdfPath> _primPaths;
    std::vector<PXR_NS::TfToken> _attributeNames;
};

void broadcastTfNoticeForAttributesChanged_abi(StageReaderWriterId stageId);

template <typename T>
T getValue(const PXR_NS::UsdAttribute& attribute, const PXR_NS::UsdTimeCode& timeCode)
{
    // First, look in fabric to see if a value is present. If not, fall back
    // to read USD's composed attribute value.

    {
        // read from fabric via StageReaderWriter, this is called during a run
        // loop where extensions are modifying one timeslice within StageWithHisotry

        // Look up the long int identifier for the attribute's UsdStage
        auto usdStageId = PXR_NS::UsdUtilsStageCache::Get().GetId(attribute.GetStage()).ToLongInt();

        // grab the interface for StageReaderWriter and use it to access the
        // (potentially NULL) current StageReaderWriter for the UsdStage
        StageReaderWriterUsd stageReaderWriterUsd(carb::getCachedInterface<omni::fabric::IStageReaderWriter>()->get(usdStageId));

        if (stageReaderWriterUsd.getId().id)
        {
            // Grab a pointer to in-memory representation for the attribute value, in this
            // case a pointer to a T. Will be NULL if attribute doesn't exist in fabric
            Path fabricPath = stageReaderWriterUsd.registerPath(attribute.GetPrimPath());
            Token fabricToken = stageReaderWriterUsd.registerToken(attribute.GetName());
            if (T* valuePtr = stageReaderWriterUsd.getAttribute<T>(fabricPath, fabricToken))
            {
                // We have a value stored for this attribute in fabric, return it
                return *valuePtr;
            }
        }
    }

    // If we get here we didn't find a value stored for this attribute in fabric,
    // so call USD API
    PXR_NS::VtValue val;
    attribute.Get(&val, timeCode);
    return val.UncheckedGet<T>();
}

template <typename T_VALUETYPE>
void setFabricValue(const PXR_NS::UsdAttribute& attribute, T_VALUETYPE value, bool writeToUSD)
{
    if (writeToUSD)
    {
        // write to the USD layer
        attribute.Set(value);
    }
    else
    {
        // write to fabric, via StageReaderWriter

        // Look up the long int identifier for the attribute's UsdSage
        auto usdStageId = PXR_NS::UsdUtilsStageCache::Get().GetId(attribute.GetStage()).ToLongInt();

        // grab the carb interface for StageReaderWriter and use it to access the
        // (potentially NULL) current StageReaderWriter for the UsdStage
        StageReaderWriterId srwId = carb::getCachedInterface<IStageReaderWriter>()->get(usdStageId);
        StageReaderWriter stageReaderWriter(srwId);
        StageReaderWriterUsd stageReaderWriterUsd(srwId);
        if (!stageReaderWriter.getId().id)
        {
            // No one created a StageReaderWriter, we're expecting this
            // to be created by another extension or run loop
            //
            // XXX: warn, or return false?
            return;
        }

        // convert the usd data to the fabric versions
        Path fabricPath = stageReaderWriterUsd.registerPath(attribute.GetPrimPath());
        Token fabricNameToken = stageReaderWriterUsd.registerToken(attribute.GetName());

        // Grab a pointer to in-memory representation for the attribute value
        if (T_VALUETYPE* valuePtr = stageReaderWriter.getAttribute<float>(fabricPath, fabricNameToken))
            *valuePtr = value;
    }
}

// This should be in UsdValueAccessors.cpp, but when it goes there
// clients in DriveSim can't find the symbol. Needs fixing.
inline void setFabricValueFloat(const PXR_NS::UsdAttribute& attribute, float value, bool writeToUSD)
{
    setFabricValue<float>(attribute, value, writeToUSD);
}

